# ==============================================================================# 060_DATABASE_MANAGER.py# IOTEC MISSION CONTROL# DATABASE MANAGER# ==============================================================================from __future__ import annotationsimport sqlite3from pathlib import Pathfrom contextlib import contextmanagerDB = Path("mission_control.db")class DatabaseManager:    def __init__(self, db_path=DB):        self.db_path = Path(db_path)    # ------------------------------------------------------------------    def connect(self):        conn = sqlite3.connect(            self.db_path,            timeout=30,            check_same_thread=False        )        conn.row_factory = sqlite3.Row        cur = conn.cursor()        cur.execute("PRAGMA journal_mode=WAL")        cur.execute("PRAGMA synchronous=NORMAL")        cur.execute("PRAGMA busy_timeout=30000")        cur.execute("PRAGMA foreign_keys=ON")        return conn    # ------------------------------------------------------------------    @contextmanager    def session(self):        conn = self.connect()        try:            yield conn            conn.commit()        except Exception:            conn.rollback()            raise        finally:            conn.close()    # ------------------------------------------------------------------    def execute(self, sql, params=()):        with self.session() as conn:            cur = conn.cursor()            cur.execute(sql, params)            return cur.rowcount    # ------------------------------------------------------------------    def executemany(self, sql, rows):        with self.session() as conn:            cur = conn.cursor()            cur.executemany(sql, rows)            return cur.rowcount    # ------------------------------------------------------------------    def fetchone(self, sql, params=()):        with self.session() as conn:            cur = conn.cursor()            cur.execute(sql, params)            row = cur.fetchone()            if row is None:                return None            return dict(row)    # ------------------------------------------------------------------    def fetchall(self, sql, params=()):        with self.session() as conn:            cur = conn.cursor()            cur.execute(sql, params)            return [dict(x) for x in cur.fetchall()]    # ------------------------------------------------------------------    def scalar(self, sql, params=()):        with self.session() as conn:            cur = conn.cursor()            cur.execute(sql, params)            row = cur.fetchone()            if row is None:                return None            return row[0]    # ------------------------------------------------------------------    def exists(self, table):        sql = """        SELECT COUNT(*)        FROM sqlite_master        WHERE type='table'        AND name=?        """        return self.scalar(sql, (table,)) > 0    # ------------------------------------------------------------------    def begin(self):        conn = self.connect()        conn.execute("BEGIN")        return conn# ==============================================================================# SINGLETON# ==============================================================================database = DatabaseManager()# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    print("=" * 70)    print("DATABASE MANAGER")    print("=" * 70)    print("Banco :", DB)    print("Existe:", DB.exists())    print()    print("Tabela missions:",          database.exists("missions"))    print("Tabela execution_logs:",          database.exists("execution_logs"))
